import sys,json,time; sys.path.insert(0,'/tmp/dbtest')
exec(open('/tmp/dbtest/edge_e2e.py').read().split("run(\"update public.payment_gateway_methods")[0])
W={'x-topline-worker-secret':'worker-secret-123'}
print('=== Brevo failure handling',flush=True)
http('POST','/__mock/config',{'brevo':'error'}); reset()
code,r=http('POST','/fn/deliver-communications',{},W); print('worker with Brevo 401 ->',code,json.dumps(r)[:260],flush=True)
check('worker survives a provider outage (no crash)', code==200, (code,r))
stat=q1("select status||':'||count(*) from public.communication_outbox where attempt_count>0 group by status order by 2 desc limit 3"); print('   rows touched (status:count):',stat,flush=True)
sample=q1("select attempt_count||'/'||max_attempts||' next='||coalesce(next_attempt_at::text,'none')||' err='||coalesce(left(error_message,70),'') from public.communication_outbox where attempt_count>0 and status<>'sent' order by last_attempt_at desc limit 1"); print('   sample:',sample,flush=True)
check('failed sends are recorded with an error message and retry time', bool(sample) and 'err=' in sample and not sample.endswith('err='), sample)
check('nothing wrongly marked sent during the outage', int(q1("select count(*) from public.communication_outbox where status='sent' and last_attempt_at>now()-interval '1 minute' and provider_message_id is null"))==0)
http('POST','/__mock/config',{'brevo':'ok'}); run("update public.communication_outbox set next_attempt_at=now()-interval '1 minute' where attempt_count>0 and status<>'sent'")
reset(); code,r=http('POST','/fn/deliver-communications',{},W); n=len([c for c in mock() if c['service']=='brevo'])
check('after Brevo recovers, messages are delivered on the next run', code==200 and n>0, (code,n))
print('=== Scheduler',flush=True)
code,r=http('POST','/fn/operations-scheduler',{'job':'expire_payment_attempts'},W); print('   ->',code,json.dumps(r)[:240],flush=True)
check('scheduler runs the new expire_payment_attempts job', code==200 and r['results'][0]['status']=='succeeded', (code,r))
check('the run is recorded in automation_job_runs', q1("select status from public.automation_job_runs where job_key='expire_payment_attempts' order by started_at desc limit 1")=='succeeded')
code,r=http('POST','/fn/operations-scheduler',{'job':'drop_database'},W); check('unknown job refused', code==400, (code,r))
code,r=http('POST','/fn/operations-scheduler',{'job':'expire_payment_attempts'},{'x-topline-worker-secret':'nope'}); check('scheduler rejects a wrong secret', code==401, (code,r))
code,r=http('POST','/fn/operations-scheduler',{},W); print('   ALL jobs ->',code,[(x['job'],x['status']) for x in r.get('results',[])] if isinstance(r,dict) else r,flush=True)
check('every scheduled job succeeds when all run together', code==200 and all(x['status']=='succeeded' for x in r['results']), r)
print(f"{sum(1 for _,c in results if c)}/{len(results)}",flush=True)
